(()=>{const form=document.querySelector('#dd-review-form');if(!form)return;const note=document.querySelector('#dd-review-note');form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('button[type=submit]');button.disabled=true;note.textContent='Submitting your review...';try{const data=Object.fromEntries(new FormData(form));data.rating=Number(data.rating);const response=await fetch('/api/reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok||!result.ok)throw Error(result.error||'Submission unavailable');form.reset();note.textContent='Thank you! Your review has been received and is awaiting approval.';}catch(err){note.textContent=err.message||'Please try again later.';}finally{button.disabled=false;}});const grid=document.querySelector('#dd-approved-reviews');if(grid)fetch('/api/reviews').then(r=>r.ok?r.json():{reviews:[]}).then(data=>{for(const item of data.reviews||[]){const card=document.createElement('article');card.className='testimonial-card';const heading=document.createElement('strong');heading.textContent=item.name;const stars=document.createElement('p');stars.textContent='★'.repeat(item.rating)+'☆'.repeat(5-item.rating);const content=document.createElement('p');content.textContent=item.review;card.append(heading,stars,content);grid.append(card);}}).catch(()=>{});})();